local BoardGameMaker = {}
local PRODUCTS = {
    wooden_board_game = { name = "Lesena namizna igra", woodCost = 2, paintCost = 1, time = 2, cost = 25, entertainment = 40, happiness = 2, description = "Lesena namizna igra za družino." },
    painted_board_game = { name = "Poslikana namizna igra", woodCost = 2, paintCost = 2, time = 4, cost = 60, entertainment = 55, prestige = 2, happiness = 3, description = "Poslikana namizna igra z barvami." },
    inlaid_board_game = { name = "Intarzirana namizna igra", woodCost = 3, boneCost = 1, paintCost = 1, time = 6, cost = 140, entertainment = 70, prestige = 5, happiness = 4, description = "Intarzirana namizna igra z okrasji." },
    silver_trim_game = { name = "Srebrno obrobljena igra", woodCost = 3, silverCost = 1, boneCost = 1, paintCost = 1, time = 9, cost = 320, entertainment = 82, prestige = 10, happiness = 5, description = "Igra s srebrnim okovjem za plemiče." },
    gold_inlaid_game = { name = "Zlato intarzirana igra", woodCost = 3, goldCost = 1, silverCost = 1, ivoryCost = 1, paintCost = 1, time = 12, cost = 700, entertainment = 92, prestige = 18, happiness = 7, description = "Zlato intarzirana igra za visoke plemiče." },
    royal_grand_game = { name = "Kraljevski veliki igra", woodCost = 5, goldCost = 2, silverCost = 1, jewelCost = 1, ivoryCost = 1, pearlCost = 1, paintCost = 2, time = 17, cost = 1800, entertainment = 100, prestige = 40, happiness = 12, description = "Velika kraljevska igra z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Igrarska delavnica", cost = { gold = 260, wood = 130, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    painting_room = { name = "Slikalnica", cost = { gold = 850, wood = 250, stone = 400, paint = 8 }, upkeep = 21, qualityBonus = 18 },
    inlay_room = { name = "Intarzijalnica", cost = { gold = 2200, wood = 350, stone = 600, silver = 25, bone = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_game_atelier = { name = "Kraljevski atelje iger", cost = { gold = 9000, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
BoardGameMaker.woodStock = 18; BoardGameMaker.paintStock = 12; BoardGameMaker.boneStock = 10; BoardGameMaker.ivoryStock = 8; BoardGameMaker.silverStock = 8; BoardGameMaker.goldStock = 6; BoardGameMaker.jewelStock = 6; BoardGameMaker.pearlStock = 4
BoardGameMaker.productStock = {}; BoardGameMaker.buildings = {}; BoardGameMaker.maker = nil; BoardGameMaker.activeMaking = {}; BoardGameMaker.totalProducts = 0; BoardGameMaker.dayTimer = 0
function BoardGameMaker.init() BoardGameMaker.woodStock=18; BoardGameMaker.paintStock=12; BoardGameMaker.boneStock=10; BoardGameMaker.ivoryStock=8; BoardGameMaker.silverStock=8; BoardGameMaker.goldStock=6; BoardGameMaker.jewelStock=6; BoardGameMaker.pearlStock=4; BoardGameMaker.productStock={}; BoardGameMaker.buildings={}; BoardGameMaker.maker=nil; BoardGameMaker.activeMaking={}; BoardGameMaker.totalProducts=0; BoardGameMaker.dayTimer=0; print("[BoardGameMaker] Royal Board Game Maker System initialized (6 products, 4 buildings)") end
function BoardGameMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BoardGameMaker.maker={name=n or ("Igrar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Igrar najet: %s (spretnost: %d)",BoardGameMaker.maker.name,s),"success") end; return true end
function BoardGameMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BoardGameMaker.build(id) local ok,e=BoardGameMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BoardGameMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BoardGameMaker.getQualityBonus() local b=0; for _,bd in ipairs(BoardGameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BoardGameMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BoardGameMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.paintCost and BoardGameMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.boneCost and BoardGameMaker.boneStock<(d.boneCost or 0) then return false,"Premalo kosti" end; if d.ivoryCost and BoardGameMaker.ivoryStock<(d.ivoryCost or 0) then return false,"Premalo slonovine" end; if d.silverCost and BoardGameMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BoardGameMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BoardGameMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BoardGameMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BoardGameMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BoardGameMaker.maker then return false,"Potreben igrar" end; return true end
function BoardGameMaker.make(pt,qty) qty=qty or 1; local ok,e=BoardGameMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BoardGameMaker.woodStock=BoardGameMaker.woodStock-d.woodCost*qty end; if d.paintCost then BoardGameMaker.paintStock=BoardGameMaker.paintStock-d.paintCost*qty end; if d.boneCost then BoardGameMaker.boneStock=BoardGameMaker.boneStock-d.boneCost*qty end; if d.ivoryCost then BoardGameMaker.ivoryStock=BoardGameMaker.ivoryStock-d.ivoryCost*qty end; if d.silverCost then BoardGameMaker.silverStock=BoardGameMaker.silverStock-d.silverCost*qty end; if d.goldCost then BoardGameMaker.goldStock=BoardGameMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BoardGameMaker.jewelStock=BoardGameMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BoardGameMaker.pearlStock=BoardGameMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BoardGameMaker.maker then t=math.max(1,t-math.floor(BoardGameMaker.maker.skill/12)) end; table.insert(BoardGameMaker.activeMaking,{id="boardgame_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,entertainment=d.entertainment or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BoardGameMaker.completeMaking(m) local q=1.0+(BoardGameMaker.getQualityBonus()/100); if BoardGameMaker.maker then q=q+(BoardGameMaker.maker.skill/180) end; q=math.min(2.0,q); BoardGameMaker.productStock[m.productType]=(BoardGameMaker.productStock[m.productType] or 0)+m.quantity; BoardGameMaker.totalProducts=BoardGameMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BoardGameMaker.maker then BoardGameMaker.maker.itemsMade=BoardGameMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then BoardGameMaker.maker.skill=math.min(100,BoardGameMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Igra izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"boardgame.completed",{productName=m.productName,entertainment=m.entertainment,prestige=m.prestige,happiness=m.happiness}) end end
function BoardGameMaker.update(dt) if not _G.state then return end; BoardGameMaker.dayTimer=BoardGameMaker.dayTimer+dt; if BoardGameMaker.dayTimer>=30 then BoardGameMaker.dayTimer=0; for i=#BoardGameMaker.activeMaking,1,-1 do local m=BoardGameMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BoardGameMaker.completeMaking(m); table.remove(BoardGameMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BoardGameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BoardGameMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BoardGameMaker.getStats() return {woodStock=BoardGameMaker.woodStock,paintStock=BoardGameMaker.paintStock,boneStock=BoardGameMaker.boneStock,ivoryStock=BoardGameMaker.ivoryStock,silverStock=BoardGameMaker.silverStock,goldStock=BoardGameMaker.goldStock,jewelStock=BoardGameMaker.jewelStock,pearlStock=BoardGameMaker.pearlStock,productStock=BoardGameMaker.productStock,numBuildings=#BoardGameMaker.buildings,hasMaker=BoardGameMaker.maker~=nil,makerName=BoardGameMaker.maker and BoardGameMaker.maker.name or "—",makerSkill=BoardGameMaker.maker and BoardGameMaker.maker.skill or 0,activeMaking=#BoardGameMaker.activeMaking,totalProducts=BoardGameMaker.totalProducts} end
return BoardGameMaker
